<?php $rows = $rows ?? []; ?><div class="table-card"><table class="table mb-0"><thead><tr><th>Title</th><th>Student</th><th>Teacher</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php if (!$rows): ?><tr><td class="empty-state" colspan="5"><i class="bi bi-inbox d-block"></i>No applications found.</td></tr><?php else: foreach ($rows as $row): ?><tr><td><a href="<?= url('application', ['id' => $row['id']]) ?>" class="fw-semibold text-decoration-none"><?= e($row['title']) ?></a></td><td><?= e($row['student_name']) ?></td><td><?= e($row['teacher_name'] ?? '-') ?></td><td><span class="badge text-bg-<?= status_class($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><?= format_date($row['created_at']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div>